package grd;
import java.util.*;
import java.util.stream.*;
import static grd.Catalog.*;

public final class Battle {
 public enum Mode{EASY(20,.72),NORMAL(30,1),HARD(40,1.15),HELL(50,1.35),ENDLESS(99999,1.12);public final int limit;final double hp;Mode(int l,double h){limit=l;hp=h;}}
 public enum Cast{NORMAL,GROUP,GAMBLE}
 public static final int[] ORDER={0,5,12,17,1,4,13,16,2,3,14,15,6,11,7,10,8,9},STAGE={8,10,12,14,16,18},EXPAND={300,500,900,1500,2400},MEMBER={100,200,400,800,1500,2500,4000},GROUP={200,350,650,1100,1800,2600,4000},TRAIN={1500,2500,4000,6000,8500,11500,15000,19000};
 public record Point(double x,double y){}
 public static Point slot(int i){return new Point(235+i%6*86,124+i/6*86);}
 public static Point point(double d){d=(d%1860+1860)%1860;if(d<600)return new Point(150+d,45);d-=600;if(d<330)return new Point(750,45+d);d-=330;if(d<600)return new Point(750-d,375);return new Point(150,375-(d-600));}
 public static final class Unit{public final int id;public final String name;public final Group group;public int slot=-1,level=1,invested=0,attacks=0;public double cd,damageDone;public boolean locked;Unit(int id,String n,Group g){this.id=id;name=n;group=g;}public boolean grouped(){return group!=null;}}
 public static final class Enemy{public double d,hp,max,speed,slow,age,left=75;public int wave,phase;public boolean boss;Enemy(int w,double hp,double speed,boolean boss){wave=w;this.hp=max=hp;this.speed=speed;this.boss=boss;}}
 static final class Batch{int wave,total,spawned,pending;double timer;boolean done;Batch(int w,int n){wave=w;total=n;}}
 public record Stats(double damage,double interval,double range,String role){}
 public record Hit(Point from,Point to,double damage,boolean critical,String color,String skill,double radius){}
 public record Notice(String title,String detail,Group group,boolean first){}
 public record Perk(String id,String name,String detail){}
 public static final List<Perk> PERKS=List.of(new Perk("world","월드 투어","그룹 공격력 +15%"),new Perk("audition","공개 오디션","캐스팅권 10장"),new Perk("encore","앙코르","스킬 필요 공격 -1"),new Perk("fan","팬미팅","12% 확률 영입권 반환"),new Perk("comeback","컴백 쇼케이스","다음 조합 2성"),new Perk("agency","대형 기획사","배치 한도 +2"),new Perk("indie","인디 레이블","4인 이하 그룹 ATK +18%"),new Perk("global","글로벌 페스티벌","7인 이상 그룹 ATK +18%"),new Perk("lucky","럭키 티켓","도박 확률 +5%p"),new Perk("viral","음원 역주행","그룹 강화 효율 증가"),new Perk("trainee","연습생 육성","멤버 ATK +22%"));
 public final Catalog catalog;public final Mode mode;public final List<Group> groups;public final List<String> members;public final List<Unit> units=new ArrayList<>();public final List<Enemy> enemies=new ArrayList<>();public final List<Hit> hits=new ArrayList<>();public final Deque<Notice> notices=new ArrayDeque<>();public final Map<String,Integer> perks=new HashMap<>(),upgrades=new HashMap<>(),credits=new HashMap<>();public final Set<String> revealed=new HashSet<>();public List<Perk> choices=List.of();final List<Batch> batches=new ArrayList<>();
 public int tickets=18,gold=800,diamonds=3,stage=0,training=0,wave=0,kills=0,cleared=0,selected=-1,speed=1;int uid,killCredit,pendingPerks;long rng;public double next=25,elapsed,autoTimer;public boolean auto,autoCombine,autoMerge,paused,done,win;public Cast autoKind=Cast.GROUP;public Group focus;public String message="STAGE READY";
 public Battle(Catalog c,Mode m,long seed,List<String> wanted){catalog=c;mode=m;rng=seed&0xffffffffL;List<Group> pick=new ArrayList<>(),rest=new ArrayList<>();for(Group g:c.groups){if(wanted.contains(g.id())&&pick.size()<3)pick.add(g);else rest.add(g);}for(int i=rest.size()-1;i>0;i--){int j=(int)(random()*(i+1));Collections.swap(rest,i,j);}for(Group g:rest)if(pick.size()<12)pick.add(g);groups=List.copyOf(pick);focus=groups.get(0);members=groups.stream().flatMap(g->g.members().stream()).distinct().toList();}
 double random(){rng=(rng*1664525+1013904223)&0xffffffffL;return rng/4294967296.0;}
 <T>T pick(List<T> a){return a.get((int)(random()*a.size()));}
 public int perk(String p){return perks.getOrDefault(p,0);}
 public int capacity(){return Math.min(18,STAGE[stage]+2*perk("agency"));}
 public boolean open(int i){for(int j=0;j<capacity();j++)if(ORDER[j]==i)return true;return false;}
 public Unit at(int slot){for(Unit u:units)if(u.slot==slot)return u;return null;}
 public Unit selected(){return units.stream().filter(u->u.id==selected).findFirst().orElse(null);}
 public int deployed(){return (int)units.stream().filter(u->u.slot>=0).count();}
 int free(){for(int i:ORDER)if(open(i)&&at(i)==null)return i;return -1;}
 Unit add(String n,Group g,int level,int hint){Unit u=new Unit(++uid,n,g);u.level=level;u.slot=open(hint)&&at(hint)==null?hint:free();units.add(u);selected=u.id;return u;}
 public int castCost(Cast c){return c==Cast.NORMAL?1:c==Cast.GAMBLE?5:focus.members().size()<=5?2:1;}
 public boolean cast(Cast c,boolean automatic){if(done||paused||!choices.isEmpty()||tickets<castCost(c))return false;int old=selected;tickets-=castCost(c);if(c==Cast.GAMBLE){if(random()<.2+.05*perk("lucky")){Group g=pick(groups);double r=random();Unit u=add(g.name(),g,r<.01?3:r<.1?2:1,-1);reveal(u);}else message="도박 실패";}else{List<String> list=c==Cast.NORMAL?members:focus.members();List<String> missing=list.stream().filter(n->units.stream().noneMatch(u->!u.grouped()&&u.name.equals(n))).toList();double p=c==Cast.NORMAL?.65:list.size()>=6?.88:list.size()>=4?.70:.35;String n=pick(!missing.isEmpty()&&random()<p?missing:list);add(n,null,1,-1);message=n+" 영입";if(perk("fan")>0&&random()<.12)tickets++;}if(automatic)selected=old;return true;}
 public void chooseMember(String n){if(!done&&!paused&&choices.isEmpty()&&diamonds>=3&&members.contains(n)){diamonds-=3;add(n,null,1,-1);message=n+" 선택 영입";}}
 public List<Unit> materials(Group g){List<Unit> ms=new ArrayList<>();for(String n:g.members()){Unit u=units.stream().filter(v->!v.grouped()&&!v.locked&&v.name.equals(n)).max(Comparator.comparingInt(v->v.level)).orElse(null);if(u!=null)ms.add(u);}return ms;}
 public boolean combine(Group g){if(done||paused||!choices.isEmpty())return false;List<Unit> ms=materials(g);int cost=g.members().size()*50;if(ms.size()!=g.members().size()||gold<cost)return false;gold-=cost;int hint=ms.stream().filter(u->u.slot>=0).mapToInt(u->u.slot).findFirst().orElse(-1);credits.merge(g.id(),ms.stream().mapToInt(u->u.invested).sum(),Integer::sum);units.removeAll(ms);int lv=perk("comeback")>0?2:1;perks.remove("comeback");Unit u=add(g.name(),g,lv,hint);reveal(u);return true;}
 void reveal(Unit u){boolean first=revealed.add(u.group.id());notices.add(new Notice(u.name,"★".repeat(u.level),u.group,first));message=u.name+" 완성";}
 public boolean merge(Unit a,Unit b){if(done||paused||!choices.isEmpty()||a==null||b==null||a==b||!a.grouped()||!b.grouped()||a.locked||b.locked||a.level!=b.level||a.level>=3||!a.group.id().equals(b.group.id()))return false;if(a.slot<0)a.slot=b.slot;a.level++;a.cd=Math.max(a.cd,b.cd);a.damageDone+=b.damageDone;a.attacks=Math.max(a.attacks,b.attacks);units.remove(b);selected=a.id;message=a.name+" "+"★".repeat(a.level);return true;}
 public boolean move(Unit u,int i){if(done||paused||!choices.isEmpty()||u==null||!units.contains(u)||!open(i))return false;Unit v=at(i);if(v==u)return false;if(v!=null&&merge(u,v)){u.slot=i;return true;}int old=u.slot;if(v!=null)v.slot=old;u.slot=i;selected=u.id;return true;}
 public void bench(Unit u){if(!paused&&!done&&choices.isEmpty()&&u!=null)u.slot=-1;}
 public int upgradeCost(Unit u){if(u==null)return -1;int n=u.grouped()?upgrades.getOrDefault(u.group.id(),0):u.level-1;int[] costs=u.grouped()?GROUP:MEMBER;if(n>=costs.length)return -1;return Math.max(0,costs[n]-(u.grouped()?credits.getOrDefault(u.group.id(),0):0));}
 public void upgrade(Unit u){int c=upgradeCost(u);if(done||paused||!choices.isEmpty()||c<0||gold<c)return;gold-=c;if(u.grouped()){String id=u.group.id();int n=upgrades.getOrDefault(id,0);credits.put(id,Math.max(0,credits.getOrDefault(id,0)-GROUP[n]));upgrades.put(id,n+1);}else{u.level++;u.invested+=c;}}
 public void sell(Unit u){if(done||paused||!choices.isEmpty()||u==null||u.locked)return;gold+=u.grouped()?50*u.group.members().size()*(1<<(u.level-1)):35+(int)(u.invested*.3);units.remove(u);selected=-1;}
 public void expand(){if(!done&&!paused&&choices.isEmpty()&&capacity()<18&&stage<5&&gold>=EXPAND[stage]){gold-=EXPAND[stage++];message="STAGE UP · "+capacity();}}
 public void train(){if(!done&&!paused&&choices.isEmpty()&&training<TRAIN.length&&gold>=TRAIN[training])gold-=TRAIN[training++];}
 public void deployAll(){if(done||paused||!choices.isEmpty())return;for(Unit u:units)if(u.slot<0){int i=free();if(i<0)break;u.slot=i;}}
 public boolean canSkip(){return !done&&!paused&&choices.isEmpty()&&wave<mode.limit&&enemies.isEmpty()&&batches.stream().allMatch(b->b.done);}
 public void skip(){if(canSkip())next=0;}
 public void choosePerk(Perk p){if(!choices.contains(p))return;perks.merge(p.id,1,Integer::sum);if(p.id.equals("audition"))tickets+=10;choices=List.of();pendingPerks=Math.max(0,pendingPerks-1);}
 void offer(){if(pendingPerks<=0||!choices.isEmpty())return;List<Perk> a=new ArrayList<>(PERKS.stream().filter(p->p.id.equals("audition")||p.id.equals("agency")&&capacity()<18||perk(p.id)==0&&!p.id.equals("agency")).toList());for(int i=a.size()-1;i>0;i--)Collections.swap(a,i,(int)(random()*(i+1)));choices=List.copyOf(a.subList(0,Math.min(3,a.size())));}
 public Stats stats(Unit u){double team=1+.12*training;if(!u.grouped()){long k=17;for(int cp:u.name.codePoints().toArray())k=(k*31+cp)&0xffffffffL;int i=(int)(k%6);double[] dm={25,48,37,44,31,41},in={.48,1.12,.78,1.05,.76,.89},rg={112,190,145,138,158,155};String[] roles={"속사","저격","기본","광역","감속","치명타"};Map<String,Object> p=obj(catalog.profiles.get(u.name));double d=num(p,"damage",dm[i]),it=num(p,"interval",in[i]),r=num(p,"range",rg[i]);String role=p.isEmpty()?roles[i]:Map.of("윤아","속사","산다라박","기본","공민지","속사","CL","저격","박봄","기본","태연","저격","제시카","광역","유리","광역").getOrDefault(u.name,roles[i]);return new Stats(Math.round(d*(1+.38*(u.level-1))*(p.isEmpty()?.9+k%19/100.0:1)*team*(1+.22*perk("trainee"))),Math.max(.28,it*(1-(u.level-1)*.025)),Math.round((r+(p.isEmpty()?k%13:0))*(roles[i].equals("저격")||r>=185?1.6:1.18)),role);}
 Group g=u.group;String role=g.role();double raw=num(catalog.raw,g.id(),0),factor=raw>0?Math.max(.94,Math.min(1.06,Math.pow(raw/500,.08))):1,base=g.damage()!=null?g.damage():38*Math.pow(g.members().size(),1.28)*factor;
 List<Unit> copies=units.stream().filter(v->v.slot>=0&&v.grouped()&&v.group.id().equals(g.id())).sorted(Comparator.comparingInt((Unit v)->-v.level).thenComparingInt(v->v.id)).toList();double[] dup={1,.72,.50,.35,.27};int index=copies.indexOf(u);double duplicate=index<0?1:index<5?dup[index]:.20;Set<Group> unique=units.stream().filter(v->v.slot>=0&&v.grouped()).map(v->v.group).collect(Collectors.toSet());long gen=g.generation().isBlank()?0:unique.stream().filter(v->v.generation().equals(g.generation())).count(),agency=g.agency().isBlank()?0:unique.stream().filter(v->v.agency().equals(g.agency())).count();double as=gen>=4?.82:gen>=3?.88:gen>=2?.94:1,at=1+(agency>=4?.24:agency>=3?.15:agency>=2?.08:0);double it=switch(role){case "저격","광역"->1.05;case "감속"->.85;case "지원"->.65;default->.75;};double r=switch(role){case "저격"->320;case "광역"->205;case "감속"->200;case "지원"->195;default->220;};double boost=(1+.15*perk("world"))*(1+(g.members().size()<=4?.18*perk("indie"):0)+(g.members().size()>=7?.18*perk("global"):0));return new Stats(Math.round(base*new double[]{1,2.5,6.25}[u.level-1]*(1+upgrades.getOrDefault(g.id(),0)*(.35+.1*perk("viral")))*duplicate*team*at*boost),(g.interval()!=null?g.interval():it)*as,g.range()!=null?g.range():r,role);}
 static double dist(Point a,Point b){return Math.hypot(a.x-b.x,a.y-b.y);}
 double hit(Unit u,Enemy e,double amount){double factor=1;int pattern=(e.wave/5-1)%6;if(e.boss){if(pattern==0&&e.age%12<4)factor=.55;if(pattern==2&&e.phase%2==0&&!u.grouped())factor=.45;if(pattern==5&&e.hp<e.max*.65&&e.hp>e.max*.35)factor=.75;}double d=amount*factor;u.damageDone+=Math.min(Math.max(e.hp,0),d);e.hp-=d;return d;}
 void attack(Unit u,Enemy e,Stats s,List<Unit> deployed){Point from=slot(u.slot),to=point(e.d);boolean support=deployed.stream().anyMatch(v->v!=u&&v.grouped()&&v.group.role().equals("지원")&&dist(slot(v.slot),from)<180);u.cd=s.interval*(support?.8:1);boolean crit=s.role.equals("치명타")&&random()<.25;double d=s.damage*(crit?2.1:1);u.attacks++;Skill sk=u.grouped()?u.group.skill():null;boolean unitSynergy=u.grouped()&&List.of(List.of("snsd","tts"),List.of("twice","misamo")).stream().anyMatch(p->p.contains(u.group.id())&&p.stream().allMatch(id->deployed.stream().anyMatch(v->v.grouped()&&v.group.id().equals(id))));boolean proc=sk!=null&&u.attacks%Math.max(2,sk.every()-perk("encore")-(unitSynergy?1:0))==0;if(proc&&List.of("pierce","critical","tempo").contains(sk.kind())){d*=sk.power();crit|=sk.kind().equals("critical");}if(proc&&sk.kind().equals("tempo"))u.cd*=.35;if(proc&&sk.kind().equals("cheer"))for(Unit v:deployed)if(v!=u&&dist(slot(v.slot),from)<220)v.cd=Math.max(0,v.cd-.18);d=hit(u,e,d);if(s.role.equals("감속"))e.slow=1.6;double radius=0;if(s.role.equals("광역")||proc&&List.of("blast","freeze").contains(sk.kind())){radius=proc?sk.radius():65;double ratio=proc&&sk.kind().equals("blast")?sk.power()*.65:.45;for(Enemy v:enemies)if(v!=e&&v.hp>0&&dist(point(v.d),to)<radius){hit(u,v,d*ratio);if(proc&&sk.kind().equals("freeze"))v.slow=3.2;}if(proc&&sk.kind().equals("freeze"))e.slow=3.2;}hits.add(new Hit(from,to,d,crit,u.grouped()?u.group.color():"#9be8e3",proc?sk.name():"",radius));}
 void spawn(Batch b){Wave w=catalog.wave(b.wave,mode.hp);boolean boss=b.wave%5==0&&b.spawned==b.total-1;double hp=boss?(b.wave==30?Math.round(Math.sqrt(255000.0*750000)*.55*mode.hp):Math.round(w.hp()*6)):w.hp();enemies.add(new Enemy(b.wave,hp,w.speed()*(boss?.72:1),boss));b.spawned++;b.pending++;}
 void end(boolean win,String text){this.win=win;done=true;auto=false;message=text;}
 public void update(double dt){if(done||paused||!choices.isEmpty())return;elapsed+=dt;if(wave<mode.limit&&(next-=dt)<=0){wave++;next=50;Wave w=catalog.wave(wave,mode.hp);batches.add(new Batch(wave,w.count()+(wave%5==0?1:0)));message="ROUND "+wave+(wave%5==0?" · BOSS":"");}
 for(Batch b:batches){b.timer-=dt;while(b.spawned<b.total&&b.timer<=0){spawn(b);b.timer+=.65;}}
 List<Enemy> extra=new ArrayList<>();for(Enemy e:enemies){e.slow=Math.max(0,e.slow-dt);e.d+=e.speed*(e.slow>0?.6:1)*dt;if(e.boss){e.left-=dt;e.age+=dt;int phase=(int)(e.age/6),pat=(e.wave/5-1)%6;if(phase>e.phase){if(pat==1)e.d+=180;if(pat==3)for(Unit u:units)if(u.slot>=0)u.cd+=.4;if(pat==4&&phase<=5){Batch b=batches.get(e.wave-1);for(int i=0;i<2;i++){Enemy v=new Enemy(e.wave,e.max*.04,e.speed*1.5,false);v.d=e.d-i*30;extra.add(v);b.pending++;}}e.phase=phase;}if(pat==5&&e.hp<e.max*.4)e.speed=Math.max(e.speed,catalog.wave(e.wave,mode.hp).speed()*1.2);}}enemies.addAll(extra);
 List<Unit> deployed=units.stream().filter(u->u.slot>=0).toList();for(Unit u:units)u.cd=Math.max(0,u.cd-dt);for(Unit u:deployed){if(u.cd>0)continue;Stats s=stats(u);Enemy e=null;for(Enemy v:enemies)if(v.hp>0&&dist(slot(u.slot),point(v.d))<=s.range&&(e==null||v.d>e.d))e=v;if(e!=null)attack(u,e,s,deployed);}
 Iterator<Enemy> iter=enemies.iterator();while(iter.hasNext()){Enemy e=iter.next();if(e.hp>0)continue;iter.remove();batches.get(e.wave-1).pending--;kills++;gold+=8+(e.wave-1)/5*8+Math.max(0,e.wave-19)*2;if(++killCredit>=(e.wave<15?15:e.wave<20?12:10)){killCredit-=e.wave<15?15:e.wave<20?12:10;tickets++;}if(e.boss){diamonds+=1+e.wave/10;gold+=300+e.wave*40;message="BOSS DOWN";if(e.wave<mode.limit)pendingPerks++;}}
 if(enemies.size()>=60||enemies.stream().anyMatch(e->e.boss&&e.left<=0)){end(false,"GAME OVER");return;}for(Batch b:batches)if(!b.done&&b.spawned==b.total&&b.pending==0){b.done=true;cleared++;tickets+=2+b.wave/5;gold+=150+b.wave*35;}if(mode!=Mode.ENDLESS&&cleared==mode.limit){end(true,"STAGE CLEAR");return;}offer();
 }
 public void automation(double real){if(paused||done||!choices.isEmpty())return;if(auto&&tickets>=castCost(autoKind)){autoTimer+=real;if(autoTimer>=.8){autoTimer=0;cast(autoKind,true);}}else autoTimer=0;if(autoCombine)combine(focus);if(autoMerge){outer:for(Unit a:new ArrayList<>(units))for(Unit b:new ArrayList<>(units))if(merge(a,b))break outer;}}
}
